dt-option.example:
new DataTable('#myTable', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList', 'pageLength']
		}
	},
	stateRestore: {
		ajax: '/states/myTable'
	}
});

new DataTable('#myTable', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList', 'pageLength']
		}
	},
	stateRestore: {
		ajax: {
			url: '/states/myTable',
			headers: {
				'x-csrftoken': TOKEN
			}
		}
	}
});
